15	/* About one point every two pixels along the larger radius. */
16	int arc_point_count(unsigned w, unsigned h, int angle2) {
17	  const int sweep = sweep_of(angle2);
18	  if (sweep == 0) return 0;
19	  const float radius = (float)(w > h ? w : h) / 2.0f;
20	  const float sweep_radians = (float)abs(sweep) / 64.0f * DEGREES_TO_RADIANS;
21	  const float n = ceilf(sweep_radians * radius / 2.0f) + 1.0f;
22	  if (n < 2.0f) return 2;
23	  return n > (float)ARC_MAX_POINTS ? ARC_MAX_POINTS : (int)n;
24	}
