22	/* The rows of a disc of each diameter up to DISC_MAX_W, relative to its corner.
23	 * canvas_fill_ellipse works each row out in double precision, which the S3 does
24	 * in software, and a round-capped line draws two discs per segment. A disc's
25	 * rows do not depend on where it sits, so they are worked out once per width.
26	 * A row with xb < xa is empty. */
27	#define DISC_MAX_W 16
28	typedef struct {
29	  int16_t xa, xb;
30	} disc_row;
31	static disc_row g_disc_rows[DISC_MAX_W + 1][DISC_MAX_W];
32	static bool g_disc_built[DISC_MAX_W + 1];
