51	/* A disc of diameter w centred on the pixel (cx, cy). Skipped when it cannot
52	 * reach the canvas. */
53	static void disc(Canvas *c, wide_t cx, wide_t cy, int w, uint16_t colour) {
54	  if (cx < -(wide_t)w || cy < -(wide_t)w || cx > (wide_t)c->w + w ||
55	      cy > (wide_t)c->h + w)
56	    return;
57	  const wide_t x = cx - w / 2, y = cy - w / 2;
58	  if (w < 1 || w > DISC_MAX_W) {
59	    canvas_fill_ellipse(c, (int)x, (int)y, w, w, colour);
60	    return;
61	  }
62	  if (!g_disc_built[w]) build_disc(w);
63	  for (int row = 0; row < w; row++) {
64	    const disc_row d = g_disc_rows[w][row];
65	    if (d.xb >= d.xa) fill_box(c, x + d.xa, y + row, x + d.xb, y + row, colour);
