101	 * ends can be anywhere in the int range. Returns 0 when nothing is left. */
102	static int clip_to_canvas(const Canvas *c, wide_t margin, double *x1,
103	                          double *y1, double *x2, double *y2) {
104	  const double xmin = -(double)margin, xmax = (double)c->w + margin;
105	  const double ymin = -(double)margin, ymax = (double)c->h + margin;
106	  const double dx = *x2 - *x1, dy = *y2 - *y1;
107	  const double p[4] = {-dx, dx, -dy, dy};
108	  const double q[4] = {*x1 - xmin, xmax - *x1, *y1 - ymin, ymax - *y1};
109	  double t0 = 0, t1 = 1;
110	  for (int i = 0; i < 4; i++) {
111	    if (p[i] == 0) {
112	      if (q[i] < 0) return 0;
113	    } else {
114	      const double t = q[i] / p[i];
115	      if (p[i] < 0) {
116	        if (t > t1) return 0;
117	        if (t > t0) t0 = t;
118	      } else {
119	        if (t < t0) return 0;
120	        if (t < t1) t1 = t;
121	      }
122	    }
123	  }
124	  const double ax = *x1 + t0 * dx, ay = *y1 + t0 * dy;
125	  const double bx = *x1 + t1 * dx, by = *y1 + t1 * dy;
126	  *x1 = ax;
127	  *y1 = ay;
128	  *x2 = bx;
129	  *y2 = by;
130	  return 1;
131	}
