136	 * edges included. The vertices stay floats: canvas_fill_polygon takes ints,
137	 * which would move the edges of a thin line by up to half a pixel. */
138	static void fill_convex(Canvas *c, const float pts[][2], int n,
139	                        uint16_t colour) {
140	  float ymin = pts[0][1], ymax = ymin;
141	  for (int i = 1; i < n; i++) {
142	    ymin = fminf(ymin, pts[i][1]);
143	    ymax = fmaxf(ymax, pts[i][1]);
144	  }
145	  const wide_t y0 = max_w(0, (wide_t)floorf(ymin));
146	  const wide_t y1 = min_w((wide_t)c->h - 1, (wide_t)ceilf(ymax));
147	  for (wide_t y = y0; y <= y1; y++) {
148	    const float sy = (float)y + 0.5f;
149	    float xl = INFINITY, xr = -INFINITY;
150	    for (int i = 0, j = n - 1; i < n; j = i++) {
151	      const float yi = pts[i][1], yj = pts[j][1];
152	      if ((yi < sy && yj >= sy) || (yj < sy && yi >= sy)) {
153	        const float x = pts[i][0] + (sy - yi) / (yj - yi) * (pts[j][0] - pts[i][0]);
154	        xl = fminf(xl, x);
155	        xr = fmaxf(xr, x);
156	      }
157	    }
158	    if (xl > xr) continue;
159	    fill_box(c, (wide_t)floorf(xl - 0.5f) + 1, y, (wide_t)floorf(xr - 0.5f), y,
