172	/* A segment between two vertices already in pixel coordinates, as a quad. An
173	 * end with a butt or round cap is lengthened enough to cover the pixel at the
174	 * vertex (half a pixel on an axis-aligned line; up to 0.71 on a diagonal when
175	 * the width is even and the vertex is a pixel corner). A projecting cap is
176	 * half the width past the vertex. An end that meets another segment
177	 * (STROKE_NO_CAP) is not lengthened at all. */
178	static void segment_quad(Canvas *c, vec2 a, vec2 b, int cap1, int cap2, int w,
179	                         uint16_t colour) {
180	  const float dx = b.x - a.x, dy = b.y - a.y;
181	  const float len = sqrtf(dx * dx + dy * dy);
182	  if (len < 0.001f) return;
183	  const float ux = dx / len, uy = dy / len;
184	  const float half = (float)w / 2.0f;
185	  const float pixel_along = (0.5f - centre_offset(w)) * (ux + uy);
186	  /* A butt cap must reach the vertex pixel (at least half a pixel). A
187	   * projecting cap reaches half the width past the vertex, which covers it,
188	   * plus the vertex pixel's offset when that is past the vertex. */
189	  const float e1 = cap1 == STROKE_NO_CAP     ? 0.0f
190	                   : cap1 == CapProjecting   ? half + fmaxf(0.0f, -pixel_along)
191	                                             : fmaxf(0.5f, -pixel_along);
192	  const float e2 = cap2 == STROKE_NO_CAP     ? 0.0f
193	                   : cap2 == CapProjecting   ? half + fmaxf(0.0f, pixel_along)
194	                                             : fmaxf(0.5f, pixel_along);
195	  const float nx = -uy * half, ny = ux * half;
196	  const vec2 p = {a.x - ux * e1, a.y - uy * e1};
197	  const vec2 q = {b.x + ux * e2, b.y + uy * e2};
198	  const float quad[4][2] = {
199	      {p.x + nx, p.y + ny}, {q.x + nx, q.y + ny}, {q.x - nx, q.y - ny},
200	      {p.x - nx, p.y - ny}};
201	  fill_convex(c, quad, 4, colour);
202	}
